CREATE FUNCTION pg_temp.rejects(q text, allowed text[]) RETURNS boolean LANGUAGE plpgsql AS $$
BEGIN EXECUTE q; RETURN false;
EXCEPTION WHEN OTHERS THEN RETURN SQLSTATE = ANY(allowed);
END $$;
SELECT pg_temp.rejects($probe$INSERT INTO "TypeSmoke" (s_min,dt2_p0,num_max_prec) VALUES ('X','2025-01-01',10000000000000000000000000000)$probe$, ARRAY['22003']);

